import {ESP_BOARDS} from './esp-boards.js';
import {bindExampleWires} from './esp-example-bindings.js';
import {createESPBench,validateESPCircuit} from './esp-circuit.js';
const wire=(pairs)=>pairs.map(([from,to],i)=>({id:'w'+i,from,to,color:from.includes('GND')||to.includes('GND')?'#64748b':from.includes('3V3')?'#ef4444':'#14b8a6'}));
const board={id:'mcu',type:'board',x:30,y:30,params:{}};
const i2c=(type,params={},extra=[])=>({components:[structuredClone(board),{id:'sensor1',type,x:390,y:90,params}],wires:wire([['mcu:3V3','sensor1:'+(type==='sht31'?'VIN':'VCC')],['mcu:GND','sensor1:GND'],['mcu:GPIO4','sensor1:'+(type==='bmp280'?'SDI':'SDA')],['mcu:GPIO5','sensor1:'+(type==='bmp280'?'SCK':'SCL')],...extra.map(([a,b])=>['sensor1:'+a,'mcu:'+b])])});
export const ESP_CIRCUIT_EXAMPLES=[
 {id:'sensor-scan',name:'I²C · Sensör tarama',detail:'SHT31 · BH1750 · iki adres',code:'#include <Wire.h>\nvoid setup(){ Serial.begin(115200); Wire.begin(4,5); }\nvoid loop(){\n for(int address=1;address<127;address++){\n  Wire.beginTransmission(address);\n  if(Wire.endTransmission()==0){Serial.print("I2C 0x");Serial.println(address,HEX);}\n }\n delay(20);\n}\n',circuit:()=>{const a=i2c('sht31',{temperature:25,humidity:50},[['ADDR','GND']]);a.components.push({id:'light1',type:'bh1750',x:530,y:90,params:{lux:120}});a.wires.push(...wire([['mcu:3V3','light1:VCC'],['mcu:GND','light1:GND'],['mcu:GPIO4','light1:SDA'],['mcu:GPIO5','light1:SCL'],['light1:ADDR','mcu:GND']]).map((w,i)=>({...w,id:'b'+i})));return a;}},
 {id:'sensor-sht31',name:'I²C · SHT31',detail:'Sıcaklık / nem · CRC-8',code:'#include <Wire.h>\nbyte crc(byte a,byte b){byte v=255;byte data[]={a,b};for(int j=0;j<2;j++){v^=data[j];for(int i=0;i<8;i++)v=(v&128)?(v<<1)^49:v<<1;}return v;}\nvoid setup(){Serial.begin(115200);Wire.begin(4,5);}\nvoid loop(){\n Wire.beginTransmission(0x44);Wire.write(0x24);Wire.write(0);\n int ack=Wire.endTransmission();delay(20);\n if(ack||Wire.requestFrom(0x44,6)!=6){Serial.println("SHT31 NO ACK");return;}\n byte b[6];for(int i=0;i<6;i++)b[i]=Wire.read();\n if(crc(b[0],b[1])!=b[2]||crc(b[3],b[4])!=b[5]){Serial.println("CRC ERROR");return;}\n unsigned raw=(unsigned(b[0])<<8)|b[1];\n Serial.print("TEMP x100=");Serial.print(int(raw*17500u/65535u)-4500);\n Serial.print(" HUM x100=");Serial.println(((unsigned(b[3])<<8)|b[4])*10000u/65535u);\n}\n',circuit:()=>i2c('sht31',{temperature:25,humidity:50},[['ADDR','GND']])},
 {id:'sensor-bh1750',name:'I²C · BH1750',detail:'Lux · 3.3 V',code:'#include <Wire.h>\nvoid setup(){Serial.begin(115200);Wire.begin(4,5);}\nvoid loop(){Wire.beginTransmission(0x23);Wire.write(0x13);int ack=Wire.endTransmission();delay(20);if(ack||Wire.requestFrom(0x23,2)!=2){Serial.println("BH1750 NO ACK");return;}unsigned raw=(Wire.read()<<8)|Wire.read();Serial.print("LUX=");Serial.println(raw*5/6);}\n',circuit:()=>i2c('bh1750',{lux:120},[['ADDR','GND']])},
 {id:'sensor-mpu6050',name:'I²C · MPU6050',detail:'Kimlik / ivme · register okuma',code:'#include <Wire.h>\nvoid setup(){Serial.begin(115200);Wire.begin(4,5);Wire.beginTransmission(0x68);Wire.write(0x6B);Wire.write(0);Wire.endTransmission();}\nvoid loop(){Wire.beginTransmission(0x68);Wire.write(0x75);int ack=Wire.endTransmission(false);if(ack||Wire.requestFrom(0x68,1)!=1){Serial.println("MPU NO ACK");return;}Serial.print("WHO=");Serial.println(Wire.read(),HEX);Wire.beginTransmission(0x68);Wire.write(0x3B);Wire.endTransmission(false);if(Wire.requestFrom(0x68,6)==6){for(int i=0;i<3;i++){int raw=(Wire.read()<<8)|Wire.read();if(raw&32768)raw-=65536;Serial.print(raw);Serial.print(" ");}Serial.println();}delay(20);}\n',circuit:()=>i2c('mpu6050',{ax:.5,ay:0,az:1,temperature:25},[['AD0','GND']])},
 {id:'sensor-oled',name:'I²C · OLED',detail:'SSD1306 · 128×64 gerçek RAM',code:'#include <Wire.h>\nvoid setup(){Serial.begin(115200);Wire.begin(4,5);Wire.beginTransmission(0x3C);Wire.write(0);byte commands[]={0xAE,0x20,0,0x21,48,79,0x22,2,5,0xAF};Wire.write(commands,sizeof(commands));Serial.print("OLED ACK=");Serial.println(Wire.endTransmission());for(int page=0;page<4;page++){for(int block=0;block<1;block++){Wire.beginTransmission(0x3C);Wire.write(0x40);for(int i=0;i<32;i++)Wire.write((i/4+page)%2?0x55:0xAA);if(Wire.endTransmission())Serial.println("OLED NO ACK");}}Serial.println("OLED FRAME DONE");}\nvoid loop(){}\n',circuit:()=>i2c('oled',{address:60})},
 {id:'sensor-adc',name:'SPI · Pot / MCP3008',detail:'Harici ADC · gerçek örnekleme',code:'#include <SPI.h>\nvoid setup(){Serial.begin(115200);SPI.begin(4,6,5,7);SPI.beginTransaction(SPISettings(20000,MSBFIRST,SPI_MODE0));}\nvoid loop(){digitalWrite(7,LOW);SPI.transfer(1);byte high=SPI.transfer(128);byte low=SPI.transfer(0);digitalWrite(7,HIGH);unsigned raw=((high&3)<<8)|low;Serial.print("ADC=");Serial.print(raw);Serial.print(" mV=");Serial.println(raw*3300u/1024u);delay(20);}\n',circuit:()=>({components:[structuredClone(board),{id:'adc1',type:'mcp3008',x:430,y:60,params:{}},{id:'pot1',type:'pot',x:330,y:320,params:{value:50,ohms:10000}}],wires:wire([['mcu:3V3','adc1:VDD'],['mcu:3V3','adc1:VREF'],['mcu:GND','adc1:DGND'],['mcu:GND','adc1:AGND'],['mcu:GPIO4','adc1:CLK'],['mcu:GPIO5','adc1:DIN'],['mcu:GPIO6','adc1:DOUT'],['mcu:GPIO7','adc1:CS'],['mcu:3V3','pot1:VCC'],['mcu:GND','pot1:GND'],['pot1:OUT','adc1:CH0']])})},
 {id:'sensor-ir',name:'GPIO · Engel sensörü',detail:'IR modülü → GPIO3 → LED',code:'void setup(){Serial.begin(115200);pinMode(3,INPUT);pinMode(2,OUTPUT);}\nvoid loop(){int obstacle=!digitalRead(3);digitalWrite(2,obstacle);Serial.print("OBSTACLE=");Serial.println(obstacle);delay(20);}\n',circuit:chip=>{const p=createESPBench(chip);p.components=p.components.filter(c=>c.type!=='button');p.wires=p.wires.filter(w=>!w.from.startsWith('btn1:')&&!w.to.startsWith('btn1:'));p.components.push({id:'ir1',type:'irObstacle',x:380,y:280,params:{active:0,activeLow:1}});p.wires.push(...wire([['mcu:3V3','ir1:VCC'],['mcu:GND','ir1:GND'],['mcu:GPIO3','ir1:OUT']]).map((w,i)=>({...w,id:'ir'+i})));return p;}}
];
ESP_CIRCUIT_EXAMPLES.push(
 {id:'sensor-bmp280',name:'I²C · BMP280',detail:'Sıcaklık / basınç registerları',code:'#include <Wire.h>\nunsigned readReg(byte a,int count){Wire.beginTransmission(0x76);Wire.write(a);if(Wire.endTransmission(false)||Wire.requestFrom(0x76,count)!=unsigned(count))return 0;unsigned n=0;while(Wire.available())n=(n<<8)|Wire.read();return n;}\nunsigned trim(byte a){unsigned n=readReg(a,2);return (n>>8)|((n&255)<<8);}\nvoid setup(){Serial.begin(115200);Wire.begin(4,5);Serial.print("BMP ID=");Serial.println(readReg(0xD0,1),HEX);}\nvoid loop(){Wire.beginTransmission(0x76);Wire.write(0xF4);Wire.write(0x25);if(Wire.endTransmission()){Serial.println("BMP NO ACK");return;}delay(10);int raw=readReg(0xFA,3)>>4;int t1=trim(0x88),t2=trim(0x8A),t3=trim(0x8C);if(t2&32768)t2-=65536;if(t3&32768)t3-=65536;int d=(raw>>4)-t1;int fine=(((raw>>3)-(t1<<1))*t2>>11)+((d*d>>12)*t3>>14);Serial.print("BMP TEMP x100=");Serial.print((fine*5+128)>>8);Serial.print(" RAW PRESSURE=");Serial.println(readReg(0xF7,3)>>4);}\n',circuit:()=>i2c('bmp280',{temperature:25,pressure:1013.25},[['CSB','3V3'],['SDO','GND']])},
 {id:'sensor-eeprom',name:'I²C · EEPROM',detail:'24LC256 · yaz / oku',code:'#include <Wire.h>\nvoid setup(){Serial.begin(115200);Wire.begin(4,5);}\nvoid loop(){Wire.beginTransmission(0x50);Wire.write(0);Wire.write(0);Wire.write(37);Wire.write(77);int ack=Wire.endTransmission();delay(10);Wire.beginTransmission(0x50);Wire.write(0);Wire.write(0);ack|=Wire.endTransmission(false);if(ack||Wire.requestFrom(0x50,2)!=2){Serial.println("EEPROM NO ACK");return;}Serial.print("EEPROM=");Serial.print(Wire.read());Serial.print("/");Serial.println(Wire.read());delay(20);}\n',circuit:()=>{const p=i2c('eeprom',{},[['A0','GND'],['A1','GND'],['A2','GND'],['WP','GND']]);for(const [id,pin]of [['rSDA','SDA'],['rSCL','SCL']]){p.components.push({id,type:'resistor',x:id==='rSDA'?540:660,y:150,params:{ohms:4700}});p.wires.push(...wire([['mcu:3V3',id+':1'],[id+':2','sensor1:'+pin]]).map((w,i)=>({...w,id:id+i})));}return p;}}
);
ESP_CIRCUIT_EXAMPLES.push(
 {id:'sensor-onewire',name:'1-Wire · DS18B20',detail:'9-bit dönüşüm · CRC-8',code:`const unsigned DQ=4;
void pullLow(){digitalWrite(DQ,LOW);pinMode(DQ,OUTPUT);}
void release(){pinMode(DQ,INPUT);}
bool resetBus(){pullLow();delayMicroseconds(500);release();delayMicroseconds(70);bool present=!digitalRead(DQ);delayMicroseconds(430);return present;}
void writeByte(byte value){for(int i=0;i<8;i++){pullLow();delayMicroseconds(value&1?6:60);release();delayMicroseconds(value&1?64:10);value>>=1;}}
byte readByte(){byte value=0;for(int i=0;i<8;i++){pullLow();delayMicroseconds(6);release();delayMicroseconds(9);value|=digitalRead(DQ)<<i;delayMicroseconds(55);}return value;}
byte crc8(byte*data){byte crc=0;for(int n=0;n<8;n++){byte value=data[n];for(int b=0;b<8;b++){byte mix=(crc^value)&1;crc>>=1;if(mix)crc^=0x8C;value>>=1;}}return crc;}
void setup(){Serial.begin(115200);release();resetBus();writeByte(0xCC);writeByte(0x4E);writeByte(75);writeByte(70);writeByte(0x1F);}
void loop(){if(!resetBus()){Serial.println("DS18B20 NO PRESENCE");delay(20);return;}writeByte(0xCC);writeByte(0x44);delay(100);resetBus();writeByte(0xCC);writeByte(0xBE);byte data[9];for(int i=0;i<9;i++)data[i]=readByte();if(crc8(data)!=data[8]){Serial.println("DS18B20 CRC ERROR");return;}int raw=(data[1]<<8)|data[0];if(raw&32768)raw-=65536;Serial.print("DS TEMP x100=");Serial.println(raw*100/16);}
`,circuit:()=>({components:[structuredClone(board),{id:'sensor1',type:'ds18b20',x:430,y:180,params:{temperature:25}},{id:'pullup1',type:'resistor',x:330,y:100,params:{ohms:4700}}],wires:wire([['mcu:3V3','sensor1:VDD'],['mcu:GND','sensor1:GND'],['mcu:GPIO4','sensor1:DQ'],['mcu:3V3','pullup1:1'],['pullup1:2','sensor1:DQ']])})},
 {id:'sensor-analog',name:'SPI · Analog sensörler',detail:'TMP36 · toprak · NTC → MCP3008',code:`#include <SPI.h>
unsigned readADC(unsigned channel){digitalWrite(7,LOW);SPI.transfer(1);byte high=SPI.transfer(128|(channel<<4));byte low=SPI.transfer(0);digitalWrite(7,HIGH);return ((high&3)<<8)|low;}
void setup(){Serial.begin(115200);SPI.begin(4,6,5,7);SPI.beginTransaction(SPISettings(20000,MSBFIRST,SPI_MODE0));}
void loop(){for(unsigned i=0;i<3;i++){Serial.print("CH");Serial.print(i);Serial.print("=");Serial.print(readADC(i));Serial.print(" ");}Serial.println();delay(20);}
`,circuit:chip=>{const p=ESP_CIRCUIT_EXAMPLES.find(e=>e.id==='sensor-adc').circuit(chip);p.components=p.components.filter(c=>c.id!=='pot1');p.wires=p.wires.filter(w=>!w.from.startsWith('pot1:')&&!w.to.startsWith('pot1:'));for(const[id,type,ch,params,y]of[['temp1','tmp36',0,{temperature:25},240],['soil1','soilCap',1,{moisture:50},320],['ntc1','thermistor',2,{temperature:25,r25:10000,beta:3950,fixed:10000,threshold:30,activeLow:1},400]]){p.components.push({id,type,x:650,y,params});p.wires.push(...wire([['mcu:3V3',id+':VCC'],['mcu:GND',id+':GND'],[id+':'+(type==='tmp36'?'OUT':'AO'),'adc1:CH'+ch]]).map((w,i)=>({...w,id:id+i})));}return p;}}
);
ESP_CIRCUIT_EXAMPLES.push({id:'sensor-relay',name:'GPIO · Sensörlü röle',detail:'IR → NPN → bobin · koruma diyodu',code:`void setup(){Serial.begin(115200);pinMode(3,INPUT);pinMode(2,OUTPUT);}
void loop(){int obstacle=!digitalRead(3);digitalWrite(2,obstacle);Serial.print("RELAY=");Serial.println(obstacle);delay(20);}
`,circuit:chip=>{const p=ESP_CIRCUIT_EXAMPLES.find(e=>e.id==='sensor-ir').circuit(chip);p.components.find(c=>c.id==='ir1').params.active=1;p.components.push({id:'base1',type:'resistor',x:430,y:190,params:{ohms:1000}},{id:'q1',type:'npn',x:610,y:170,params:{beta:100,vbe:.7,vceSat:.2}},{id:'relay1',type:'coilRelay',x:700,y:45,params:{nominalVoltage:5,coilOhms:70}},{id:'flyback1',type:'diode',x:850,y:190,params:{vf:.7}});p.wires.push(...wire([['mcu:GPIO2','base1:1'],['base1:2','q1:B'],['q1:E','mcu:GND'],['q1:C','relay1:A2'],['mcu:5V','relay1:A1'],['flyback1:A','relay1:A2'],['flyback1:K','relay1:A1']]).map((w,i)=>({...w,id:'relay'+i})));return p;}});
export const espExampleCircuit=(id,chip)=>{const raw=(ESP_CIRCUIT_EXAMPLES.find(e=>e.id===id)?.circuit(ESP_BOARDS[chip].target||chip)||createESPBench(ESP_BOARDS[chip].target||chip));raw.wires=bindExampleWires(chip,raw.wires);return validateESPCircuit(raw,chip);};
